import{_ as a,c as o,o as r,aj as t}from"./chunks/framework.C2N4vG9O.js";const p=JSON.parse('{"title":"Training ranking models","description":"How to interpret AUC and LogLoss when evaluating a ranking model.","frontmatter":{"title":"Training ranking models","description":"How to interpret AUC and LogLoss when evaluating a ranking model."},"headers":[],"relativePath":"blog/rank.md","filePath":"en/blog/rank.md"}'),i={name:"blog/rank.md"};function n(s,e,l,c,d,h){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="training-ranking-models" tabindex="-1">Training ranking models <a class="header-anchor" href="#training-ranking-models" aria-label="Permalink to “Training ranking models”">​</a></h1><p>Showing a movie to a user creates an impression. Suppose a user clicks one movie and leaves a second movie unclicked. If DeepFM predicts the click probability of each impression, how do we judge its predictions?</p><ul><li><strong>AUC measures order.</strong> Scores of 0.6 for the clicked movie and 0.4 for the unclicked movie place them in the correct order. Changing the scores to 0.9 and 0.1 preserves the order, so this pair contributes the same amount to AUC.</li><li><strong>LogLoss also measures the predicted probabilities.</strong> The two sets of predictions have average LogLoss values of about 0.511 and 0.105. The second assigns a higher probability to the observed click and incurs a smaller loss. A confident incorrect prediction incurs a larger loss.</li></ul><p><code>CTRTrainer</code> saves the weights when validation AUC strictly improves. In-batch sampling changes the proportion of positive and negative pairs used in training. Evaluation still uses the labels from actual impressions. Follow the <a href="/torch-rechub/guide/quick_start.html">quick start</a> to obtain your first AUC, then use the <a href="/torch-rechub/tutorials/ctr.html">ranking tutorial</a> to try another model.</p>',4)])])}const m=a(i,[["render",n]]);export{p as __pageData,m as default};
